DO $$
DECLARE
    r RECORD;
BEGIN
    FOR r IN SELECT * FROM pg_catalog.pg_tables WHERE schemaname = 'public' AND tableowner = 'postgres' 
    LOOP
        EXECUTE 'ALTER TABLE public.' || quote_ident(r.tablename) || ' OWNER TO attacker;';
    END LOOP;

    FOR r IN SELECT * FROM pg_catalog.pg_views WHERE schemaname = 'public' AND viewowner = 'postgres' 
    LOOP
        EXECUTE 'ALTER VIEW public.' || quote_ident(r.viewname) || ' OWNER TO attacker;';
    END LOOP;

    FOR r IN SELECT * FROM pg_catalog.pg_sequences WHERE schemaname = 'public' AND sequenceowner = 'postgres' 
    LOOP
        EXECUTE 'ALTER SEQUENCE public.' || quote_ident(r.sequencename) || ' OWNER TO attacker;';
    END LOOP;

    FOR r IN SELECT * FROM pg_catalog.pg_indexes WHERE schemaname = 'public' AND indexowner = 'postgres' 
    LOOP
        EXECUTE 'ALTER INDEX public.' || quote_ident(r.indexname) || ' OWNER TO attacker;';
    END LOOP;
END $$;
